Lemma rl14_A3c : forall regs m (DW DX SX sy dy swpl dwpl datas datad nfw cdx csx : Z) (mk : word),
  (1 <= DW < 2 ^ 31)%Z -> (0 <= DX < 2 ^ 31)%Z -> (0 <= SX < 2 ^ 31)%Z ->
  nfw = (DW / 32)%Z -> cdx = (DX / 32)%Z -> csx = (SX / 32)%Z -> (0 <= nfw < 2 ^ 26)%Z -> (0 <= cdx < 2 ^ 26)%Z -> (0 <= csx < 2 ^ 26)%Z ->
  (0 <= sy < 2 ^ 24)%Z -> (0 <= swpl)%Z -> (sy * swpl < 2 ^ 24)%Z -> (0 <= dy < 2 ^ 24)%Z -> (0 <= dwpl)%Z -> (dy * dwpl < 2 ^ 24)%Z ->
  (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  rdn SEGS m (Z_to_bv 64 0x1f39c) 4 = Some (Z_to_le_bytes 4 374328) ->
  getr regs 6 = Z_to_bv 64 DW -> getr regs 23 = Z_to_bv 64 sy -> getr regs 13 = Z_to_bv 64 swpl -> getr regs 26 = Z_to_bv 64 SX ->
  getr regs 27 = Z_to_bv 64 dy -> getr regs 14 = Z_to_bv 64 dwpl -> getr regs 21 = Z_to_bv 64 13 -> getr regs 22 = Z_to_bv 64 datas ->
  getr regs 5 = Z_to_bv 64 datad -> getr regs 19 = Z_to_bv 64 DX -> getr regs 7 = mk ->
  exists regs',
    msteps SEGS (mkst regs (0x7a2c4 : word) m rom) (mkst regs' (0x7aa1c : word) m rom)
    /\ getr regs' 10 = Z_to_bv 64 0
    /\ getr regs' 8 = Z_to_bv 64 (datad + 4 * (dy * dwpl) + 4 * cdx) /\ getr regs' 17 = Z_to_bv 64 (datad + 4 * (dy * dwpl) + 4 * cdx)
    /\ getr regs' 31 = Z_to_bv 64 (datas + 4 * (sy * swpl) + 4 * csx) /\ getr regs' 16 = Z_to_bv 64 (datas + 4 * (sy * swpl) + 4 * csx)
    /\ getr regs' 5 = Z_to_bv 64 (4 * dwpl) /\ getr regs' 29 = Z_to_bv 64 (4 * swpl) /\ getr regs' 30 = Z_to_bv 64 32
    /\ (1 <= nfw -> getr regs' 28 = Z_to_bv 64 (4 * nfw))%Z
