Lemma rl14_Hf : forall regs m (DW : Z), (32 <= DW < 2 ^ 31)%Z ->
  getr regs 6 = Z_to_bv 64 DW -> getr regs 30 = Z_to_bv 64 32 ->
  exists regs', msteps SEGS (mkst regs (0x7aa1c : word) m rom) (mkst regs' (0x7aa24 : word) m rom)
    /\ getr regs' 18 = Z_to_bv 64 0 /\ regs_agree (fun r => In r [18]%list) regs regs'.
Proof.
