(* [comment removed for export] *)
Lemma rl14_I : forall (last : bool) regs m (srow drow off n4 : Z) (bs bd : list byte) (v vd : word),
  (0 <= srow)%Z -> (0 <= drow)%Z -> (0 <= off)%Z -> (off + 4 <= n4)%Z -> (n4 < 2 ^ 32)%Z -> (srow + n4 < 2 ^ 64)%Z -> (drow + n4 < 2 ^ 64)%Z ->
  (if last then off + 4 = n4 else off + 4 < n4)%Z ->
  rdn SEGS m (Z_to_bv 64 (srow + off)) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v ->
  rdn SEGS m (Z_to_bv 64 (drow + off)) 4 = Some bd -> bytes_le_to_Z bd = bv_unsigned vd ->
  store_ok SEGS m (Z_to_bv 64 (drow + off)) 4 = true ->
  getr regs 31 = Z_to_bv 64 srow -> getr regs 8 = Z_to_bv 64 drow -> getr regs 18 = Z_to_bv 64 off -> getr regs 28 = Z_to_bv 64 n4 ->
  exists regs' (w : word),
    msteps SEGS (mkst regs (0x7aa24 : word) m rom)
                (mkst regs' (if last then (0x7aa44 : word) else (0x7aa24 : word)) (wbytes m (Z_to_bv 64 (drow + off)) (word_to_le_bytes 4 w)) rom)
    /\ getr regs' 18 = Z_to_bv 64 (off + 4)
