(* [comment removed for export] *)
Lemma rl14_N1 : forall regs m (i dh srow drow s4 d4 : Z),
  (0 <= i)%Z -> (i + 1 < dh)%Z -> (dh < 2 ^ 31)%Z ->
  getr regs 10 = Z_to_bv 64 i -> getr regs 12 = Z_to_bv 64 dh -> getr regs 8 = Z_to_bv 64 drow -> getr regs 31 = Z_to_bv 64 srow ->
  getr regs 5 = Z_to_bv 64 d4 -> getr regs 29 = Z_to_bv 64 s4 ->
  exists regs',
    msteps SEGS (mkst regs (0x7aa08 : word) m rom) (mkst regs' (0x7aa1c : word) m rom)
    /\ getr regs' 10 = Z_to_bv 64 (i + 1) /\ getr regs' 8 = Z_to_bv 64 (drow + d4) /\ getr regs' 31 = Z_to_bv 64 (srow + s4)
    /\ regs_agree (fun r => In r [8; 10; 31]%list) regs regs'.
